import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> {'side','price','qty','seq','active'}
    seq = 0

    for order in orders:
        seq += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            rec = book.get(oid)
            if rec and rec['active'] and rec['qty'] > 0:
                rec['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            # discard invalid (cancelled/filled) entries at top
            while opp_heap:
                top = opp_heap[0]
                topid = top[-1]
                toprec = book.get(topid)
                if toprec is None or not toprec['active'] or toprec['qty'] <= 0:
                    heapq.heappop(opp_heap)
                else:
                    break
            if not opp_heap:
                break

            top = opp_heap[0]
            toprec = book[top[-1]]
            top_price = toprec['price']

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, toprec['qty'])
            if side == 'buy':
                trades.append([oid, top[-1], top_price, trade_qty])
            else:
                trades.append([top[-1], oid, top_price, trade_qty])

            remaining -= trade_qty
            toprec['qty'] -= trade_qty

            if toprec['qty'] == 0:
                toprec['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit':
            if remaining > 0:
                rec = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                book[oid] = rec
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}
        # ioc and market: remainder discarded, not added to book

    return trades

